def _components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objs.append((color,cells))
    return objs

def _has_enclosed_zero(cells):
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    filled=set(cells); seen=set(); stack=[]
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r in (r0,r1) or c in (c0,c1)) and (r,c) not in filled:
                seen.add((r,c)); stack.append((r,c))
    while stack:
        r,c=stack.pop()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if r0<=rr<=r1 and c0<=cc<=c1 and (rr,cc) not in filled and (rr,cc) not in seen:
                seen.add((rr,cc)); stack.append((rr,cc))
    return any((r,c) not in filled and (r,c) not in seen
               for r in range(r0,r1+1) for c in range(c0,c1+1))

def transform(grid):
    h,w=len(grid),len(grid[0]); objects=[]
    for color,cells in _components(grid):
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        objects.append((_has_enclosed_zero(cells),r0,c0,color,cells))
    out=[[0]*w for _ in range(h)]
    for upward in (True,False):
        group=sorted((o for o in objects if o[0]==upward),key=lambda o:o[1],reverse=not upward)
        for _,r0,c0,color,cells in group:
            height=max(r for r,c in cells)-r0+1
            target=0 if upward else h-height
            while True:
                conflict=False
                for r,c in cells:
                    rr=target+r-r0
                    if not 0<=rr<h or out[rr][c]:
                        conflict=True; break
                if not conflict: break
                target += 1 if upward else -1
            for r,c in cells:
                out[target+r-r0][c]=color
    return out
